import Foundation

/// Decides whether a pasteboard change should be skipped.
public struct IgnoreRules: Equatable, Sendable {
    /// Pasteboard types that mark content as secret, temporary or machine-generated.
    /// The `org.nspasteboard.*` identifiers are the community convention that
    /// password managers and other apps use (see nspasteboard.org).
    public static let defaultPasteboardTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "net.antelle.keeweb",
    ]

    public var ignoredPasteboardTypes: Set<String>
    /// Bundle identifiers of apps whose copies are never recorded.
    public var ignoredApps: Set<String>
    /// Kinds of content that are recorded. Everything else is skipped.
    public var recordedKinds: Set<ClipKind>

    public init(
        ignoredPasteboardTypes: Set<String> = IgnoreRules.defaultPasteboardTypes,
        ignoredApps: Set<String> = [],
        recordedKinds: Set<ClipKind> = Set(ClipKind.allCases)
    ) {
        self.ignoredPasteboardTypes = ignoredPasteboardTypes
        self.ignoredApps = ignoredApps
        self.recordedKinds = recordedKinds
    }

    public func shouldRecord(_ kind: ClipKind) -> Bool {
        recordedKinds.contains(kind)
    }

    public func shouldIgnore(pasteboardTypes: [String], sourceApp: String?) -> Bool {
        if let sourceApp, ignoredApps.contains(sourceApp) { return true }
        return pasteboardTypes.contains { ignoredPasteboardTypes.contains($0) }
    }
}
